package com.reevil.client.jill;

import com.reevil.ReEvilMod;
import com.reevil.client.mrx.MrXModel;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.resources.ResourceLocation;

/** Own silhouette (generated by tools/variantgen.py): the MrXModel rig, so all clips apply, with replaced/added parts. */
public class JillModel extends MrXModel {
    public static final ModelLayerLocation LAYER = new ModelLayerLocation(new ResourceLocation(ReEvilMod.MODID, "jill"), "main");
    public JillModel(ModelPart root) { super(root); }
    @Override
    protected com.reevil.anim.AnimClip clip(com.reevil.entity.mrx.MrXEntity e, int id) {
        com.reevil.anim.AnimClip c = com.reevil.client.mrx.SignatureClips.wesker(id);
        return c != null ? c : super.clip(e, id);
    }
    public static LayerDefinition createBodyLayer() {
        MeshDefinition mesh = MrXModel.mesh();
        PartDefinition root = mesh.getRoot();
        root.getChild("base").getChild("torso").getChild("neck").getChild("head").addOrReplaceChild("bob", CubeListBuilder.create()
            .texOffs(0, 64).addBox(-4.5f, -8, -4.5f, 9, 3, 9)
            .texOffs(36, 64).addBox(-4.5f, -6, 0.5f, 9, 7, 4)
            .texOffs(62, 64).addBox(-4.5f, -6, -4.5f, 1.5f, 4, 4)
            .texOffs(74, 64).addBox(3, -6, -4.5f, 1.5f, 4, 4),
            PartPose.ZERO);
        root.getChild("base").getChild("torso").addOrReplaceChild("device", CubeListBuilder.create()
            .texOffs(86, 64).addBox(-2, -8, -2.8f, 4, 4, 1)
            .texOffs(96, 64).addBox(-4.6f, -10, -2.6f, 9.2f, 1, 5.2f),
            PartPose.ZERO);
        return LayerDefinition.create(mesh, 128, 80);
    }
}
